// src/display-name.ts
import { type Result, err, ok } from '@tenets/result';

export type DisplayNameError = {
	readonly type: 'empty_display_name';
	readonly message: string;
};

/** @description Rejects a blank display name; trims before accepting. */
export function parseDisplayName(value: string): Result<string, DisplayNameError> {
	const trimmed = value.trim();

	if (trimmed.length === 0) {
		return err({ type: 'empty_display_name', message: 'Display name must not be empty.' });
	}

	return ok(trimmed);
}
```

