import { describe, expect, it } from 'vitest';

import { parseDisplayName } from './display-name';

describe('parseDisplayName', () => {
	it('returns EmptyDisplayNameError for a whitespace-only name', () => {
		// Given: a name that is only whitespace
		// When: parseDisplayName validates it
		// Then: it returns a typed rejection with the expected message
		const result = parseDisplayName('   ');

		expect(isErr(result)).toBe(true);
