			expect(result.error).toEqual({
				type: 'empty_display_name',
				message: 'Display name must not be empty.',
			});
		}
	});

	it('accepts and trims a non-empty name', () => {
		const result = parseDisplayName('  Ada  ');
		expect(result).toEqual({ ok: true, value: 'Ada' });
